<script setup lang="ts">
import { computed, nextTick, reactive, ref, watch } from 'vue';import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';import { useSessionStore } from '../stores/session';import { useResponsiveDrawer } from '../province-monitoring';
import { admissionDate } from '../admission';import { subjectError } from '../subject-management';import { fenceTypes,parseCoordinates } from '../operations-supervision';import OperationsMap from './OperationsMap.vue';
const props=defineProps<{modelValue:boolean;fenceId:string;options:any}>(),emit=defineEmits<{'update:modelValue':[boolean];saved:[any]}>(),session=useSessionStore(),width=useResponsiveDrawer(850);
const visible=computed({get:()=>props.modelValue,set:(v:boolean)=>emit('update:modelValue',v)}),mapRef=ref<any>(),formRef=ref<any>(),loading=ref(false),saving=ref(false),error=ref(''),coordinates=ref(false),drawing=ref(false);
const initial=()=>({businessNo:`WL-${session.user?.workspace?.cityCode??'SD'}-${new Date().getFullYear()}-${Date.now().toString().slice(-6)}`,name:'',fenceType:'SPEED_LIMIT',enterpriseId:'',organizationId:session.user?.organizationId??'',validFrom:admissionDate(new Date().toISOString()),validTo:'',active:false,speedLimit:15,allowedHours:'00:00-24:00',ruleDescription:'',vehicleIds:[] as string[],polygonText:''});
const form=reactive(initial());let initialJson='',generation=0;
const vehicleOptions=computed(()=>props.options.vehicles.filter((v:any)=>!form.enterpriseId||v.enterpriseId===form.enterpriseId));
const preview=computed<any[]>(()=>{try{return [{id:'draft',...form,active:true,polygon:parseCoordinates(form.polygonText)}]}catch{return []}});
const required={required:true,message:'请填写该项',trigger:'blur'};
async function load(){const n=++generation;loading.value=true;error.value='';drawing.value=false;coordinates.value=false;Object.assign(form,initial());try{if(props.fenceId){const row=await api<any>(`/safety/fences/${props.fenceId}`);if(n!==generation)return;Object.assign(form,{businessNo:row.businessNo,name:row.name,fenceType:row.fenceType,enterpriseId:row.enterpriseId??'',organizationId:row.organizationId,validFrom:admissionDate(row.validFrom),validTo:row.validTo?admissionDate(row.validTo):'',active:row.active,speedLimit:row.speedLimit??15,allowedHours:row.allowedHours??'00:00-24:00',ruleDescription:row.ruleDescription??'',vehicleIds:row.vehicles.map((x:any)=>x.vehicle.id),polygonText:row.polygon.map((p:any)=>`${p.longitude},${p.latitude}`).join('\n')})}initialJson=JSON.stringify(form)}catch(e){if(n===generation)error.value=subjectError(e)}finally{if(n===generation)loading.value=false}}
watch(()=>[props.modelValue,props.fenceId],()=>{if(props.modelValue)load();else{generation++;mapRef.value?.cancelPolygonDraw()}},{immediate:true});
function enterpriseChanged(){form.vehicleIds=[];const e=props.options.enterprises.find((e:any)=>e.id===form.enterpriseId);if(e)form.organizationId=e.organizationId}
async function draw(){if(drawing.value){mapRef.value?.cancelPolygonDraw();drawing.value=false;return}await nextTick();drawing.value=!!await mapRef.value?.beginPolygonDraw();if(!drawing.value)ElMessage.warning('地图尚未就绪，请重试或展开坐标录入')}
function drawn(p:any[]){drawing.value=false;form.polygonText=p.map(v=>`${v.longitude.toFixed(7)},${v.latitude.toFixed(7)}`).join('\n');ElMessage.success('围栏边界已绘制，可继续填写规则')}
async function close(done?:()=>void){if(saving.value)return;if(JSON.stringify(form)!==initialJson){try{await ElMessageBox.confirm('未保存的围栏调整将丢失，确定关闭？','关闭编辑',{confirmButtonText:'放弃调整',cancelButtonText:'继续编辑',type:'warning'})}catch{return}}if(done)done();else visible.value=false}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;let polygon;try{polygon=parseCoordinates(form.polygonText)}catch(e){return ElMessage.warning(subjectError(e))}saving.value=true;try{const payload:any={...form,enterpriseId:form.enterpriseId||null,validTo:form.validTo||null,polygon};delete payload.polygonText;const row=await api<any>(props.fenceId?`/safety/fences/${props.fenceId}`:'/safety/fences',{method:props.fenceId?'PATCH':'POST',body:JSON.stringify(payload)});initialJson=JSON.stringify(form);visible.value=false;ElMessage.success(props.fenceId?'围栏已更新':'围栏已创建');emit('saved',row)}catch(e){ElMessage.error(subjectError(e))}finally{saving.value=false}}
</script>
<template><el-drawer v-model="visible" :title="fenceId?'编辑电子围栏':'新建电子围栏'" :size="width" class="subject-drawer" destroy-on-close :before-close="close" :close-on-click-modal="false">
 <div v-if="error" class="subject-error" role="alert"><strong>围栏资料加载失败</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-skeleton v-else-if="loading" :rows="10"/><template v-else>
 <div class="fence-map-editor"><OperationsMap ref="mapRef" mode="fences" :fences="preview" :selected-id="'draft'" height="330px" @polygon-drawn="drawn"/><div class="fence-drawing-help">{{drawing?'单击落点，双击最后一点完成；可取消后重新绘制':'在地图绘制一块完整区域，边界内应用相应管制规则'}}</div><el-button @click="draw">{{drawing?'取消绘制':'重新绘制'}}</el-button><el-button class="fence-coordinate-toggle" link @click="coordinates=!coordinates">{{coordinates?'收起坐标录入':'展开坐标录入'}}</el-button><el-input v-if="coordinates" v-model="form.polygonText" type="textarea" :rows="5" aria-label="围栏边界坐标" placeholder="每行一组 经度,纬度"/></div>
 <el-form ref="formRef" :model="form" label-position="top" class="subject-form" style="margin-top:20px">
  <el-form-item label="围栏名称" prop="name" :rules="required"><el-input v-model.trim="form.name" maxlength="80" aria-label="围栏名称"/></el-form-item><el-form-item label="围栏编号" prop="businessNo" :rules="required"><el-input v-model.trim="form.businessNo" :disabled="!!fenceId" aria-label="围栏编号"/></el-form-item>
  <el-form-item label="围栏类型" prop="fenceType"><el-select v-model="form.fenceType" aria-label="编辑围栏类型"><el-option v-for="key in ['SPEED_LIMIT','NO_ENTRY','TEMPORARY']" :key="key" :label="fenceTypes[key]" :value="key"/></el-select></el-form-item>
  <el-form-item label="管理机构" prop="organizationId" :rules="required"><el-select v-model="form.organizationId" aria-label="围栏管理机构"><el-option v-for="o in options.organizations" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
  <el-form-item label="适用企业"><el-select v-model="form.enterpriseId" clearable filterable placeholder="公共规则（全部企业）" aria-label="围栏适用企业" @change="enterpriseChanged"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item>
  <el-form-item label="适用车辆"><el-select v-model="form.vehicleIds" multiple collapse-tags filterable clearable placeholder="范围内全部车辆" aria-label="围栏适用车辆"><el-option v-for="v in vehicleOptions" :key="v.id" :label="v.name" :value="v.id"/></el-select></el-form-item>
  <el-form-item label="生效日期" prop="validFrom" :rules="required"><el-date-picker v-model="form.validFrom" type="date" value-format="YYYY-MM-DD" aria-label="围栏生效日期"/></el-form-item><el-form-item label="截止日期"><el-date-picker v-model="form.validTo" type="date" value-format="YYYY-MM-DD" placeholder="长期" clearable aria-label="围栏截止日期"/></el-form-item>
  <el-form-item label="生效时段" prop="allowedHours" :rules="{pattern:/^(?:[01]\d|2[0-3]):[0-5]\d-(?:(?:[01]\d|2[0-3]):[0-5]\d|24:00)$/,message:'请填写 HH:mm-HH:mm',trigger:'blur'}"><el-input v-model="form.allowedHours" placeholder="07:00-19:00" aria-label="围栏生效时段"/></el-form-item>
  <el-form-item v-if="form.fenceType==='SPEED_LIMIT'" label="限速值（km/h）"><el-input-number v-model="form.speedLimit" :min="1" :max="80" aria-label="围栏限速值"/></el-form-item><el-form-item label="启用状态"><el-switch v-model="form.active" active-text="已启用" inactive-text="未启用"/></el-form-item>
  <el-form-item class="wide" label="规则说明"><el-input v-model="form.ruleDescription" type="textarea" :rows="3" maxlength="1000" aria-label="围栏规则说明"/></el-form-item>
 </el-form><p class="fence-rule-readonly">车辆获准运行的范围由通行许可确定，电子围栏维护附加的禁行、限速与临时管制。</p></template>
 <template #footer><el-button :disabled="saving" @click="close()">取消</el-button><el-button type="primary" :loading="saving" :disabled="loading||!!error" @click="save">保存围栏</el-button></template>
</el-drawer></template>
